python3 << 'EOF'
import urllib.request
import ssl
import json

# Try BLS API v2
ssl_context = ssl.create_default_context()
ssl_context.check_hostname = False
ssl_context.verify_mode = ssl.CERT_NONE

url = 'https://api.bls.gov/publicAPI/v2/timeseries/data/'
payload = {
    "seriesid": ["CUUR0000SA0"],
    "startyear": "1968",
    "endyear": "1970"
}

headers = {
    'User-Agent': 'Mozilla/5.0',
    'Content-Type': 'application/json'
}

try:
    import json
    req = urllib.request.Request(url, data=json.dumps(payload).encode('utf-8'), headers=headers, method='POST')
    response = urllib.request.urlopen(req, context=ssl_context, timeout=15)
    data = response.read().decode('utf-8')
    result = json.loads(data)

    if result.get('status') == 'REQUEST_SUCCEEDED':
        series = result.get('Results', {}).get('series', [])
        if series:
            for s in series:
                print(f"Series: {s.get('seriesID')}")
                for dp in s.get('data', []):
                    if dp.get('year') in ['1968', '1969']:
                        print(f"  {dp.get('year')}: {dp.get('periodName')}: {dp.get('value')}")
except Exception as e:
    print(f"Error: {e}")
EOF
